  "recommendations": {
    "crlm/3/standard/3": {
      "source": "Leave an asymptomatic primary in situ during systemic therapy when liver disease is broadly unresectable; resect it for a defined local threat, and before transplantation after a favourable response.",
      "concise": "Broadly unresectable liver disease: leave an asymptomatic primary during systemic therapy. Resect for a local threat, and before transplant after favorable response."
    },
    "crlm/2/standard/4": {
      "source": "After clearance, run the longitudinal loop: imaging and CEA at 3–6 months then by risk, ablation margins re-read at 4–8 weeks, colonoscopic follow-up, over a two-year and five-year framework.",
      "concise": "After clearance: imaging/CEA at 3–6 months, then by risk; review ablation margins at 4–8 weeks; colonoscopy and 2-/5-year follow-up."
    },
    "crlm/1/standard/2": {
      "source": "Resulted RAS, BRAF, mismatch-repair or microsatellite status and HER2 at diagnosis of metastatic disease, with broader profiling where a rare actionable alteration would change treatment.",
      "concise": "At metastatic diagnosis: obtain RAS, BRAF, MMR/MSI and HER2 results; broaden profiling when an actionable finding would change treatment."
    },
    "crlm/2/standard/1": {
      "source": "Thermal ablation alone or with resection is a curative-intent clearance option for small lesions, provided every original site is treated and a circumferential margin is confirmed.",
      "concise": "Small lesions: curative-intent ablation ± resection, treating every original site with a confirmed circumferential margin."
    },
    "icca/1/standard/0": {
      "source": "There is no imaging-only diagnosis of intrahepatic cholangiocarcinoma: unlike hepatocellular carcinoma, where LR-5 imaging in an at-risk population is diagnostic, histologic confirmation is required before systemic therapy or a tissue-defined transplant assessment; selected clearly resectable masses may proceed directly to surgery after multidisciplinary review.",
      "concise": "No imaging-only diagnosis. Histology is required before systemic therapy or tissue-defined transplant assessment. Selected clearly resectable masses may proceed directly to surgery after multidisciplinary review."
    },
    "icca/10/standard/2": {
      "source": "Read the supporting evidence for what it is: in 15 patients with a single tumour of 2 cm or less, the 5-year recurrence risk was 18% versus 61% for larger or multifocal disease, with 5-year survival 65% versus 45% — in explants where the cancer was first diagnosed on explant pathology.",
      "concise": "Evidence: 15 patients with a single tumor ≤2 cm, cancer first diagnosed on explant pathology. Recurrence and survival figures are in the evidence panel."
    },
    "icca/8/standard/0": {
      "source": "Have the adjuvant conversation with the numbers in front of you: BILCAP's intention-to-treat primary analysis did <b>not</b> meet statistical significance — median overall survival 51.1 versus 36.4 months, adjusted hazard ratio 0.81 (95% CI 0.63–1.04), p=0.097.",
      "concise": "Discuss adjuvant therapy with the BILCAP limitations: its primary intention-to-treat survival analysis was not statistically significant."
    },
    "icca/9/standard/0": {
      "source": "Cisplatin–gemcitabine with a checkpoint inhibitor is the first-line standard: ABC-02 established the backbone (overall survival 11.7 versus 8.1 months, hazard ratio 0.64, 95% CI 0.52–0.80), durvalumab added a hazard ratio of 0.80 and pembrolizumab 0.83.",
      "concise": "First line: cisplatin–gemcitabine plus a checkpoint inhibitor (durvalumab or pembrolizumab). Trial outcomes and effect sizes are in the evidence panel."
    },
    "hilar/4/standard/0": {
      "source": "Refer potentially eligible patients to the transplant team before primary-tumor biopsy, chemotherapy or radiation outside the transplant protocol, or attempted resection. Coordinate assessment in parallel with surgical planning; do not delay an indicated curative resection. Do not perform transperitoneal biopsy of the primary perihilar tumor, including percutaneous or EUS-guided biopsy, while transplantation remains an option. Coordinate ERCP brushings or intraductal sampling and, when indicated, regional lymph-node sampling with the team; do not delay urgent drainage or infection treatment.",
      "concise": "Refer potentially eligible patients before primary biopsy, treatment outside the transplant protocol, or attempted resection; assess in parallel without delaying indicated curative resection. Do not perform transperitoneal primary biopsy (including EUS/percutaneous) while transplant remains an option. Coordinate intraductal/ERCP and indicated regional-node sampling. Do not delay urgent drainage or infection treatment."
    },
    "hilar/1/standard/1": {
      "source": "Record the Bismuth-Corlette type as shorthand for the pattern of ductal involvement, but do not let it decide resectability — vascular involvement, lobar atrophy, nodal status and remnant volume do that.",
      "concise": "Record Bismuth–Corlette (ductal pattern); it does not decide resectability. Assess vascular involvement, lobar atrophy, nodes and remnant volume."
    },
    "hilar/3/standard/0": {
      "source": "Extended hepatectomy with en bloc extrahepatic bile duct resection, regional lymphadenectomy and biliary reconstruction, with portal vein resection and reconstruction where it is required to achieve R0.",
      "concise": "Extended hepatectomy with en bloc extrahepatic bile duct resection, regional nodes and biliary reconstruction; portal-vein resection/reconstruction when needed for R0."
    },
    "nelm/9/standard/1": {
      "source": "Maintain the allocation record and assign responsibility for renewals from the start: diagnosis and histology, baseline burden, primary and last-treatment dates, serial response imaging, extrahepatic staging, request and extension dates, score route, and named coordinator and physician sign-off.",
      "concise": "Maintain complete allocation/renewal records with a named coordinator and physician sign-off. Required record elements are listed in the information panel."
    },
    "nelm/5/standard/0": {
      "source": "Operate for meaningful reduction of hepatic burden with parenchymal-sparing resection — often multiple small wedges — using ablation as an adjunct for lesions unsuited to resection, and resect the primary where appropriate.",
      "concise": "For meaningful burden reduction: parenchymal-sparing resection, adjunct ablation for unsuitable lesions, and primary resection when appropriate."
    },
    "nelm/3/standard/0": {
      "source": "Continue the somatostatin analogue for functional-syndrome control where it is needed, and after clinically significant progression in a nonfunctional tumour do not automatically continue it for antiproliferative benefit.",
      "concise": "Continue SSA when needed for functional symptoms. After clinically significant progression in nonfunctional disease, do not automatically continue SSA for antiproliferative benefit."
    },
    "nelm/1/standard/3": {
      "source": "State the hepatic tumour burden, unilobar versus bilobar, resectable versus diffuse-miliary pattern, the primary site and whether it is resected, the extrahepatic sites, and which problem is driving the clinical picture.",
      "concise": "Document liver burden/distribution/resectability, primary site and resection, extrahepatic sites, and the main clinical problem."
    },
    "chcca/5/standard/1": {
      "source": "Use the OPTN National Liver Review Board transplant-oncology criteria as the operative threshold, because those are the criteria the exception request will be judged against — biopsy-proven mixed HCC-iCCA, solitary and 3 cm or less, cirrhosis, unresectable, six months of stability after locoregional or systemic therapy, no extrahepatic disease, score MMaT-3.",
      "concise": "NLRB exception review: biopsy-proven mixed HCC–iCCA, solitary ≤3 cm, cirrhosis, unresectable, 6 months stability after local/systemic therapy, no extrahepatic disease; MMaT−3."
    },
    "chcca/1/standard/1": {
      "source": "If the transplant pathway is in play, tissue is mandatory, not optional — the OPTN review-board criteria require biopsy-proven mixed HCC-iCCA, and the transperitoneal-route prohibition you apply in perihilar disease does not carry over here.",
      "concise": "Transplant assessment requires biopsy-proven mixed HCC–iCCA. The pCCA transperitoneal-biopsy prohibition does not apply here."
    },
    "chcca/7/standard/1": {
      "source": "Order multigene panel testing in every patient entering systemic therapy, and screen for trial eligibility at the same visit — there are now open trials in this histology, and the only one that ever randomised patients closed with four.",
      "concise": "Before systemic therapy: multigene panel and trial screening. The only randomized trial closed with four patients."
    },
    "chcca/0/standard/0": {
      "source": "The diagnosis is histological. WHO 2019 requires unequivocal hepatocytic and cholangiocytic differentiation within a single tumour, made on routine haematoxylin and eosin, with immunostains supportive rather than essential.",
      "concise": "WHO 2019: unequivocal hepatocytic AND cholangiocytic differentiation within one tumor on H&E. Immunostains are supportive, not essential."
    },
    "adenoma/4/standard/0": {
      "source": "Treat a lesion that is persistently larger than 5 cm, or growing by 20% or more, as an indication for curative treatment — and say plainly, to the patient and in the note, that 5 cm is a convention and not a derived threshold.",
      "concise": "Persistent size >5 cm or growth ≥20% is an indication for curative treatment. Explain that 5 cm is a conventional threshold."
    },
    "adenoma/5/alt/1": {
      "source": "Where the bleeding lesion is exophytic, peripheral and small and the patient is stable in a centre without interventional radiology, a limited resection is a reasonable alternative to transfer.",
      "concise": "Stable patient, small peripheral/exophytic bleeding lesion, no local IR: limited resection may be an alternative to transfer."
    },
    "adenoma/5/standard/0": {
      "source": "Resuscitate with blood products, get a contrast-enhanced CT, and transfer to a centre that can embolise — embolisation, not resection, is the first manoeuvre in the unstable patient.",
      "concise": "Unstable bleeding: blood-product resuscitation, contrast CT and transfer for embolization; embolization precedes resection."
    },
    "adenoma/2/standard/2": {
      "source": "Reimage with contrast-enhanced MRI at 6 months, and treat that scan as a trajectory rather than a verdict — six months is too early to call risk-factor modification a failure.",
      "concise": "Repeat contrast MRI at 6 months; assess trajectory. This is too early to declare risk-factor modification unsuccessful."
    },
    "incidental/0/alt/1": {
      "source": "In a liver with a vascular disorder — Budd-Chiari, chronic portal vein occlusion, obliterative portal venopathy, hereditary haemorrhagic telangiectasia, cardiac congestion — treat the case as its own category and get it to a benign-liver-tumour multidisciplinary review rather than through either arm of this assessment.",
      "concise": "Vascular liver disorder: use a separate benign-liver-tumor multidisciplinary assessment, outside this pathway’s two arms."
    },
    "incidental/5/alt/0": {
      "source": "In a liver with a vascular disorder, treat regenerative and focal-nodular-hyperplasia-like nodules as a specific entity to be managed under the vascular-liver-disease guideline, with an interval set by the multidisciplinary team rather than copied from LI-RADS.",
      "concise": "Vascular liver disorder with regenerative/FNH-like nodules: follow vascular-liver-disease guidance and team-set intervals, not LI-RADS intervals."
    },
    "incidental/7/standard/0": {
      "source": "Do not perform a transperitoneal or primary-tumour needle biopsy in a patient with suspected perihilar cholangiocarcinoma until the transplant pathway has been reviewed — this is the local programme's written safety rule and it is not a weighing of evidence.",
      "concise": "Suspected pCCA: do not perform transperitoneal or primary-tumor needle biopsy until the transplant pathway has been reviewed (local safety rule)."
    },
    "incidental/0/standard/2": {
      "source": "In a liver that is not at risk, accept that no imaging criterion set exists that can call a lesion hepatocellular carcinoma — EASL 2025 says so explicitly, and the consequence is that an unresolved solid lesion here needs tissue, not another category.",
      "concise": "Outside the HCC at-risk population, imaging criteria cannot establish HCC. An unresolved solid lesion requires tissue."
    },
    "pdac/2/standard/3": {
      "source": "Biliary drainage is not routinely recommended before an operation that is about to happen — drain for cholangitis or fever, for severely symptomatic jaundice, or because surgery is being delayed, including for neoadjuvant therapy.",
      "concise": "No routine drainage before imminent surgery. Drain for cholangitis/fever, severe symptomatic jaundice or delayed surgery, including neoadjuvant therapy."
    },
    "pdac/2/standard/0": {
      "source": "In a patient going straight to resection with a high clinical suspicion, do not wait for tissue — biopsy proof of malignancy is not required before resection, and a non-diagnostic biopsy should not delay it.",
      "concise": "High suspicion with planned upfront resection: biopsy confirmation is unnecessary; a nondiagnostic biopsy should not delay surgery."
    },
    "pdac/1/standard/0": {
      "source": "Place the patient in exactly one of resectable, borderline resectable, locally advanced or metastatic, by consensus at a multidisciplinary meeting, using the stated degrees of contact.",
      "concise": "Multidisciplinary staging by vessel-contact criteria: exactly one of resectable, borderline resectable, locally advanced or metastatic."
    },
    "pdac/7/standard/0": {
      "source": "Multiagent induction chemotherapy for a patient with adequate performance status, good biliary drainage and adequate nutritional intake — with the reassessment date set when it starts.",
      "concise": "Multiagent induction chemotherapy if performance, biliary drainage and nutrition permit; schedule reassessment at treatment start."
    },
    "pnet/4/standard/1": {
      "source": "State the actual evidence for the threshold when you offer observation: three uncontrolled cohorts with two to four years of follow-up, no randomised comparison, and not one direct comparison of the two strategies in any of them.",
      "concise": "Observation evidence: three uncontrolled cohorts, 2–4 years follow-up; no randomized or direct strategy comparison."
    },
    "pnet/5/alt/0": {
      "source": "Enucleation and central pancreatectomy are legitimate for a small, superficial tumour clear of the main duct - at a centre doing enough of them, and with the nodal question settled before the incision.",
      "concise": "Small, superficial tumor clear of the main duct: consider enucleation/central pancreatectomy at an experienced center, with the nodal question settled before incision."
    },
    "pnet/3/alt/0": {
      "source": "Where contrast CT or MRI and endoscopic ultrasound have not found the insulinoma, the next test is GLP-1 receptor imaging or arterial stimulation with venous sampling, not another anatomic study.",
      "concise": "Unlocalized insulinoma after CT/MRI and EUS: GLP-1 receptor imaging or arterial stimulation with venous sampling, not another anatomic study."
    },
    "pnet/7/standard/1": {
      "source": "In MEN1, resect a functional tumour whatever its size, observe a nonfunctional tumour under 1 cm, and resect above 2 cm or on significant growth — accepting that surgery will not clear the gland.",
      "concise": "MEN1: resect functional tumors at any size; observe nonfunctional <1 cm; resect >2 cm or significant growth. Surgery will not clear the gland."
    },
    "pcyst/2/standard/0": {
      "source": "Resect, in a patient fit for pancreatectomy, for jaundice with a head cyst, an enhancing mural nodule of 5 mm or more or a solid component, a main pancreatic duct of 10 mm or more, or cytology suspicious or positive for high-grade dysplasia or carcinoma.",
      "concise": "If fit for pancreatectomy, resect for: jaundice with a head cyst; enhancing mural nodule ≥5 mm or solid component; main duct ≥10 mm; or suspicious/positive high-grade dysplasia/carcinoma cytology."
    },
    "pcyst/1/standard/0": {
      "source": "Characterise the cyst on MRI with MRCP and write the main pancreatic duct diameter down in millimetres, because the 5 mm and 10 mm duct thresholds are what separate surveillance from an operation.",
      "concise": "MRI/MRCP: characterize the cyst and record main duct diameter in mm; 5-/10-mm thresholds affect management."
    },
    "pcyst/8/alt/1": {
      "source": "Consider earlier resection in a young fit patient facing decades of surveillance, and say that the argument is about the duration of the commitment rather than about the cyst.",
      "concise": "Consider earlier resection in young, fit patients facing decades of surveillance; explain that surveillance duration motivates this choice."
    },
    "pcyst/9/alt/0": {
      "source": "Where surveillance stops but the patient is still fit, consider stopping for the cyst while remaining alert to a concomitant adenocarcinoma elsewhere in the gland.",
      "concise": "In a fit patient, consider stopping cyst surveillance while remaining alert to a separate pancreatic adenocarcinoma."
    },
    "ampullary/1/standard/0": {
      "source": "Treat a biopsy that reads adenoma as the least severe possible diagnosis, not the final one — the reported false-negative rate for invasive carcinoma beneath an ampullary adenoma is 20% to 40%, and the cause is sampling, not interpretation.",
      "concise": "An adenoma biopsy does not exclude underlying carcinoma: reported sampling false-negative rate 20–40%."
    },
    "ampullary/9/standard/0": {
      "source": "After endoscopic papillectomy or surgical ampullectomy, perform duodenoscopy with biopsies of the scar and of any abnormal area within the first 3 months, at 6 and 12 months, and yearly thereafter for at least 5 years.",
      "concise": "After papillectomy/ampullectomy: duodenoscopy with scar/abnormal-area biopsies within 3 months, at 6 and 12 months, then yearly for ≥5 years."
    },
    "ampullary/2/alt/0": {
      "source": "Piecemeal resection with ablation of visible residual tissue, accepting a materially higher recurrence rate, where en bloc is not achievable and the alternative is a pancreatoduodenectomy for a benign lesion.",
      "concise": "If en bloc removal is impossible and benign disease would otherwise require pancreatoduodenectomy: consider piecemeal resection plus residual-tissue ablation, accepting higher recurrence."
    },
    "ampullary/0/standard/3": {
      "source": "Name the tumour by its epicentre and stop writing <i>periampullary</i> once the specimen is in hand — ampullary, duodenal, distal bile duct and pancreatic head cancers share an operation and not a prognosis.",
      "concise": "Name the histologic primary by epicenter: ampulla, duodenum, distal bile duct or pancreatic head. Shared surgery does not imply shared prognosis."
    },
    "hcc/C/alt/0": {
      "source": "Add external beam radiotherapy or radioembolisation alongside systemic therapy. Both supporting trials used a sorafenib comparator: RTOG 1112 missed its primary survival endpoint (HR 0.77, 90% CI 0.59–1.01, one-sided p=0.06) and 15% of its patients then never started sorafenib, while the Asan trial gave TACE plus radiotherapy instead of sorafenib, with 91% crossover. Neither tested adding radiation to an immunotherapy backbone.",
      "concise": "Consider radiation or radioembolization with systemic therapy. Evidence used sorafenib comparators; RTOG 1112 missed its primary survival endpoint, and Asan used TACE–radiation. Neither tested an immunotherapy backbone."
    },
    "hcc/B/standard/0": {
      "source": "Superselective conventional or drug-eluting-bead TACE. Plan selective delivery, define the intended response, and specify when to stop or change treatment.",
      "concise": "Superselective conventional/DEB-TACE: define delivery, response target and when to stop or switch."
    },
    "hcc/C/standard/0": {
      "source": "Systemic therapy is the main treatment. Start an immunotherapy combination when eligible and do not delay it for a liver-directed procedure.",
      "concise": "Systemic therapy is primary. If eligible, start an immunotherapy combination; do not delay it for a liver-directed procedure."
    }
  }
};

